use Elementor\Controls_Manager;
use Elementor\Widget_Base;

abstract class BlueVPN_Elementor_Widget_Base extends Widget_Base {
    public function get_categories() { return ['general']; }
    public function get_icon() { return 'eicon-shield'; }
    protected function add_text_control($id, $label, $default, $textarea=false) {
        $this->add_control($id, ['label'=>$label,'type'=>$textarea?Controls_Manager::TEXTAREA:Controls_Manager::TEXT,'default'=>$default,'label_block'=>true]);
    }
    protected function add_link_control($id, $label, $default) {
        $this->add_control($id, ['label'=>$label,'type'=>Controls_Manager::URL,'default'=>['url'=>$default],'show_external'=>false,'label_block'=>true]);
    }
    protected function url($settings, $key, $fallback) {
        $url = (string)($settings[$key]['url'] ?? '');
        return $url !== '' ? $url : $fallback;
    }
}

